def binary_search(arr: list, target: int) -> int:
    """Returns the index of target in sorted arr, or -1 if not found."""
    low = 0
    high = len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1
```

